namespace Tarification.Domaine;

/// <summary>Les articles et la remise appliquée, avant les frais de port.</summary>
public sealed record BilanArticles
{
    public Montant Articles { get; }
    public Montant Remise { get; }

    public BilanArticles(Montant articles, Montant remise)
    {
        _ = articles.Moins(remise);
        Articles = articles;
        Remise = remise;
    }

    public Montant Net => Articles.Moins(Remise);
}

namespace Tarification.Domaine;

/// <summary>Le bilan des articles, les frais et le montant net à payer.</summary>
public sealed record ChiffrageDuPanier(BilanArticles Bilan, Montant FraisDePort)
{
    public Montant ATPayer => Bilan.Net + FraisDePort;
}

namespace Tarification.Domaine;

/// <summary>Un article et sa quantité, au prix unitaire du moment.</summary>
public sealed record LigneDePanier(string Reference, Quantite Quantite, Montant PrixUnitaire)
{
    public Montant SousTotal => PrixUnitaire.Multiplie(Quantite.Valeur);

    public Montant Remise(PaliersDeRemise paliers)
    {
        var taux = paliers.TauxPour(Quantite);
        return taux.AppliqueA(SousTotal);
    }
}

namespace Tarification.Domaine;

/// <summary>
/// Une somme d'argent, en euros. Type-valeur : deux montants égaux sont interchangeables, et un
/// montant négatif n'existe pas dans ce domaine — un remboursement serait un autre concept.
/// </summary>
public readonly record struct Montant : IComparable<Montant>
{
    public decimal Euros { get; }

    private Montant(decimal euros) => Euros = euros;

    public static Montant De(decimal euros) =>
        euros < 0 ? throw new ArgumentOutOfRangeException(nameof(euros), euros, "Un montant ne peut pas être négatif.") : new Montant(euros);

    public static Montant Zero { get; } = new(0m);

    public static Montant operator +(Montant premier, Montant second)
    {
        var eurosDuPremier = premier.Euros;
        return new(eurosDuPremier + second.Euros);
    }

    public Montant Multiplie(int facteur) =>
        facteur < 0 ? throw new ArgumentOutOfRangeException(nameof(facteur), facteur, "Un facteur négatif n'a pas de sens ici.") : new Montant(Euros * facteur);

    internal Montant Part(TauxDeRemise taux) => De(Euros * taux.Pourcentage / 100m);

    public Montant Moins(Montant remise) => De(Euros - remise.Euros);

    public int CompareTo(Montant autre)
    {
        var eurosDeLAutre = autre.Euros;
        return Euros.CompareTo(eurosDeLAutre);
    }

    public override string ToString() => $"{Euros:0.00} €";
}

namespace Tarification.Domaine;

/// <summary>Un seuil de quantité de ligne et le taux de remise qu'il ouvre.</summary>
public readonly record struct PalierDeRemise(Quantite Seuil, TauxDeRemise Taux)
{
    public TauxDeRemise TauxPour(Quantite quantite) =>
        quantite.Atteint(Seuil) ? Taux : default;
}

namespace Tarification.Domaine;

/// <summary>Les paliers communs à toutes les références ; vide quand aucun n'est configuré.</summary>
public sealed record PaliersDeRemise
{
    private readonly PalierDeRemise[] _paliers;

    private PaliersDeRemise(PalierDeRemise[] paliers) => _paliers = (PalierDeRemise[])paliers.Clone();

    public static PaliersDeRemise De(params PalierDeRemise[] paliers) => new(paliers);

    public TauxDeRemise TauxPour(Quantite quantite) =>
        _paliers.Aggregate(default(TauxDeRemise), (taux, palier) => PlusAvantageux(taux, palier, quantite));

    private static TauxDeRemise PlusAvantageux(TauxDeRemise taux, PalierDeRemise palier, Quantite quantite)
    {
        var admissible = palier.TauxPour(quantite);
        return taux.LePlusAvantageux(admissible);
    }

    public bool Equals(PaliersDeRemise? autre) =>
        autre is not null && _paliers.SequenceEqual(autre._paliers);

    public override int GetHashCode() =>
        _paliers.Aggregate(0, CombineEmpreinte);

    private static int CombineEmpreinte(int empreinte, PalierDeRemise palier) =>
        HashCode.Combine(empreinte, palier);
}

namespace Tarification.Domaine;

/// <summary>Les lignes retenues par un client. Un panier peut être vide : son total vaut zéro.</summary>
public sealed class Panier
{
    private readonly List<LigneDePanier> _lignes = [];

    public IReadOnlyList<LigneDePanier> Lignes => _lignes;

    public Panier Ajoute(LigneDePanier ligne)
    {
        _lignes.Add(ligne);
        return this;
    }

    public Montant SommeDesLignes()
    {
        var totalInitial = Montant.Zero;
        return _lignes.Aggregate(totalInitial, AdditionneSousTotal);
    }

    private static Montant AdditionneSousTotal(Montant total, LigneDePanier ligne) =>
        total + ligne.SousTotal;

    public ChiffrageDuPanier Chiffrer(PaliersDeRemise paliers) =>
        new(new BilanArticles(SommeDesLignes(), SommeDesRemises(paliers)), Montant.Zero);

    private Montant SommeDesRemises(PaliersDeRemise paliers)
    {
        var remiseInitiale = Montant.Zero;
        return _lignes.Aggregate(remiseInitiale, (remise, ligne) => AdditionneRemise(remise, ligne, paliers));
    }

    private static Montant AdditionneRemise(Montant remise, LigneDePanier ligne, PaliersDeRemise paliers) =>
        remise + ligne.Remise(paliers);
}

namespace Tarification.Domaine;

/// <summary>Un nombre d'articles. Au moins un : une ligne de panier vide n'a pas lieu d'être.</summary>
public readonly record struct Quantite
{
    public int Valeur { get; }

    private Quantite(int valeur) => Valeur = valeur;

    public static Quantite De(int valeur) =>
        valeur < 1 ? throw new ArgumentOutOfRangeException(nameof(valeur), valeur, "Une quantité vaut au moins 1.") : new Quantite(valeur);

    public bool Atteint(Quantite seuil) => Valeur >= seuil.Valeur;

    public override string ToString() => Valeur.ToString();
}

namespace Tarification.Domaine;

/// <summary>Un pourcentage de remise, entre 0 et 100 inclus.</summary>
public readonly record struct TauxDeRemise
{
    public decimal Pourcentage { get; }

    private TauxDeRemise(decimal pourcentage) => Pourcentage = pourcentage;

    public static TauxDeRemise De(decimal pourcentage) =>
        pourcentage is < 0 or > 100
            ? throw new ArgumentOutOfRangeException(nameof(pourcentage), pourcentage, "Un taux de remise est compris entre 0 et 100.")
            : new(pourcentage);

    public Montant AppliqueA(Montant montant) => montant.Part(this);

    public TauxDeRemise LePlusAvantageux(TauxDeRemise autre) =>
        Pourcentage >= autre.Pourcentage ? this : autre;
}

